-- input:  keyboard and/or controller

-- Make color 0 transparent for sprites
poke(0x3FFB, 0)

-- =====================
-- SPRITE IDS / FRAMES
-- =====================
SPR_PLAYER_FRAMES = {257, 258, 259}
SPR_BARREL_FRAMES = {261, 262}
SPR_FIREBALL = 256
SOLID_TILES = { [2]=true, [7]=true, [10]=true }

-- =====================
-- CONSTANTS
-- =====================
ROOM_W = 240
ROOM_H = 136
TILE = 8
GRAVITY = 0.2
JUMP = -4.5
SPEED = 1.2
PLAYER_W = 8
PLAYER_H = 8
NUM_ROOMS = 10

-- =====================
-- PLAYER STATE
-- =====================
-- player position
px, py = 2, 80
vx, vy = 0, 0
jump_vx = 0
on_ground = false
facing = 1
anim_t = 0  -- animation timer

-- =====================
-- ROOM HAZARD DATA
-- =====================
ROOMS = {
    -- room 1
    { fireballs = {},
      barrels = { {x=11, y=14, s=1, anim=0}, {x=29, y=14, s=1, anim=0} } },

    -- room 2
    { fireballs = { {x=7, y=6, s=1.5}, {x=24, y=1, s=1.5} },
      barrels = {} },

    -- room 3
    { fireballs = { {x=1, y=1, s=1.0} },
      barrels = { {x=29, y=14, s=1, anim=0} } },

    -- room 4
    { fireballs = {}, barrels = {} },

    -- room 5
    { fireballs = { {x=0, y=1, s=1.2}, {x=6, y=9, s=1.0}, {x=19, y=1, s=1.0} },
      barrels = {} },

    -- room 6
    { fireballs = {},
      barrels = { {x=9, y=14, s=1, anim=0}, {x=22, y=14, s=1, anim=0}, {x=24, y=14, s=1, anim=0} } },

    -- room 7
    { fireballs = {},
      barrels = { {x=15, y=14, s=1, anim=0}, {x=26, y=14, s=1, anim=0} } },

    -- room 8
    { fireballs = { {x=19, y=0, s=1.2}, {x=27, y=1, s=1.0}, {x=25, y=7, s=1.0} },
      barrels = { {x=10, y=14, s=1, anim=0}, {x=13, y=14, s=1, anim=0}, {x=24, y=14, s=1, anim=0} } },

    -- room 9
    { fireballs = { {x=0, y=3, s=1.5}, {x=4, y=7, s=1.5} },
      barrels = { {x=18, y=14, s=1, anim=0}, {x=29, y=14, s=1, anim=0} } },

    -- room 10
    { fireballs = { {x=12, y=6, s=1.0}, {x=4, y=3, s=1.3}, {x=25, y=4, s=1.1}, {x=14, y=0, s=1.1} },
      barrels = { {x=11, y=14, s=1, anim=0}, {x=26, y=14, s=1, anim=0} } },
}

current_room = 1
fireballs = {}
barrels = {}

-- =====================
-- GOAL OBJECT (PIXEL POSITION RESTORED)
-- =====================
goal = { x=12*18, y=8*12, collected=false, sprite=260 }

-- game win check
game_won = false
-- shows license information
show_title = true
title_timer = 300
game_over = false

-- =====================
-- LOAD ROOM
-- =====================
function load_room(n)
    local room = ROOMS[n]
    if not room then return end

    fireballs = {}
    for _, f in ipairs(room.fireballs) do
        table.insert(fireballs, {x=f.x*TILE, y=f.y*TILE, s=f.s})
    end

    barrels = {}
    for _, b in ipairs(room.barrels) do
        table.insert(barrels, {x=b.x*TILE, y=b.y*TILE, s=b.s, anim=b.anim})
    end

    px, py = 2, 80
    vx, vy = 0, 0
    jump_vx = 0
    on_ground = false

    -- Restore original pixel goal position for room 4
    if n == 4 then
        goal.collected = false
        goal.x = 12*18
        goal.y = 8*12
    end
end

-- =====================
-- checks for ground and hazard
-- =====================
function solid_at(px, py)
    local tx = math.floor(px/TILE)
    local ty = math.floor(py/TILE)
    return SOLID_TILES[mget(tx, ty)] == true
end

function hit(ax, ay, aw, ah, bx, by, bw, bh)
    return ax<bx+bw and ax+aw>bx and ay<by+bh and ay+ah>by
end

-- =====================
-- PLAYER UPDATE
-- =====================
function update_player()
    if btnp(4) and on_ground then
        vy = JUMP
        on_ground = false
        jump_vx = vx
    end
				-- move lock code while jumping
    if on_ground then
        vx = 0
        if btn(2) then vx=-SPEED; facing=-1 end
        if btn(3) then vx=SPEED; facing=1 end
        jump_vx=vx
    else
        vx=jump_vx
    end
				-- jump code
    vy = vy + GRAVITY
    px = px + vx
    py = py + vy
				-- checks if floor is solid
    local bottom = py + PLAYER_H
    if solid_at(px+1,bottom) or solid_at(px+PLAYER_W/2,bottom) or solid_at(px+PLAYER_W-1,bottom) then
        py = math.floor(bottom/TILE)*TILE - PLAYER_H
        vy = 0
        on_ground = true
    else
        on_ground = false
    end

    if px<0 then px=0 end
    if current_room==4 and px+PLAYER_W>ROOM_W then px=ROOM_W-PLAYER_W end
end

-- =====================
-- HAZARDS
-- =====================
function update_fireballs()
    for _,f in ipairs(fireballs) do
        f.y=f.y+f.s
        if f.y>ROOM_H then f.y=-8 end
        if hit(px,py,PLAYER_W,PLAYER_H,f.x,f.y,8,8) then game_over=true end
    end
end

function update_barrels()
    for _,b in ipairs(barrels) do
        b.x=b.x-b.s
        b.anim=(b.anim+1)%2
        if b.x<-8 then b.x=ROOM_W end
        if hit(px,py,PLAYER_W,PLAYER_H,b.x,b.y,8,8) then game_over=true end
    end
end

-- =====================
-- DRAW FUNCTIONS
-- =====================
function draw_player()
    local frame = math.abs(vx)>0 and (math.floor(anim_t/6)%3+1) or 1
    spr(SPR_PLAYER_FRAMES[frame], px, py, 0, 1, facing==-1 and 1 or 0)
end

function draw_fireballs() for _,f in ipairs(fireballs) do spr(SPR_FIREBALL,f.x,f.y,0) end end
function draw_barrels() for _,b in ipairs(barrels) do spr(SPR_BARREL_FRAMES[b.anim+1],b.x,b.y,0) end end
function draw_goal() if current_room==4 and not goal.collected then spr(goal.sprite,goal.x,goal.y,0) end end

-- =====================
-- MAIN LOOP
-- =====================
function TIC()
    -- Title screen
    if show_title then
        cls(0)
        -- copyright and license notices
        print("Copyright (C) 2025 Daniel",0,10,12,false,1,true)
        print("Hanrahan Tools and Games",0,20,12,false,1,true)
        print("SPDX-License-Identifier: GPL-3.0-or-later",0,30,12,false,1,true)
        print("A copy of the GNU General Public License is",0,40,12,false,1,true)
        print("included in the file COPYING; if not, see",0,50,12,false,1,true)
        print("<https://www.gnu.org/licenses/>.",0,60,12,false,1,true)
        print("Information just about the stuff in this",0,70,12,false,1,true)
        print("software not covered by the GNU General",0,80,12,false,1,true)
        print("Public License version 3: This work is",0,90,12,false,1,true)
        print("licensed under Attribution-ShareAlike",0,100,12,false,1,true)
        print("4.0 International",0,110,12,false,1,true)
       	-- timer code
        title_timer = title_timer - 1
        if title_timer <= 0 then
            show_title=false
            current_room=math.random(NUM_ROOMS)
            load_room(current_room)
        end
        return
    end
				-- game over code
    if game_over then
        cls(0)
        print("GAME OVER",90,60,12)
        print("PRESS Z TO RESTART",50,80,14)
        if btnp(4) then
            game_over=false
            game_won=false
            current_room=math.random(NUM_ROOMS)
            load_room(current_room)
        end
        return
    end

    cls(0)
    map((current_room-1)*30,0,30,17,0,0)

    update_player()
    update_fireballs()
    update_barrels()

    draw_fireballs()
    draw_barrels()
    draw_player()
    draw_goal()

    if px>ROOM_W then
        local next_room
        repeat next_room=math.random(NUM_ROOMS) until next_room~=current_room
        current_room=next_room
        load_room(current_room)
    end
				-- goal code
    if current_room==4 and not goal.collected then
        if hit(px,py,PLAYER_W,PLAYER_H,goal.x,goal.y,8,8) then
            goal.collected=true
            game_won=true
        end
    end
				-- win state code
    if game_won then
        cls(0)
        print("YOU HAVE DEFEATED THE GAME!",40,60,12)
    end

    anim_t = anim_t + 1
end

